using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using LWS.TruckHockey;
using LWS.TruckWallball;
using LWS.TruckBowling;
namespace LWS.TruckSports {
public sealed class SportsExpansionSmoke:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 Keyboard keyboard;InputSettings original,probe;
 readonly Stack<IEnumerator> stack=new Stack<IEnumerator>();readonly List<string> evidence=new List<string>();bool ended,errors;string folder;float diagnosticAt;HockeyMatch hockey;WallballMatch wall;BowlingMatch bowling;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsExpansionExisting")<0)return;var g=new GameObject("Existing sports expansion native validation");DontDestroyOnLoad(g);g.AddComponent<SportsExpansionSmoke>();}
 void Start(){folder=LWS.TruckSports.SportsEvidencePaths.Folder("ExpansionEvidence");Directory.CreateDirectory(folder);original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Expansion software keyboard");InputSystem.QueueStateEvent(keyboard,new KeyboardState());Application.logMessageReceived+=Log;stack.Push(Run());}
 void Log(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){errors=true;evidence.Add("ERROR "+message);}}
 void Check(bool good,string label){if(!good)throw new Exception(label);evidence.Add("PASS "+label);Debug.Log("TS_EXPANSION_PHYSICAL_PASS "+label);}
 void Note(string line){evidence.Add(line);Debug.Log("TS_EXPANSION_EVIDENCE "+line);}
 IEnumerator Delay(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}
 IEnumerator Wait(Func<bool> predicate,float seconds,string label){float end=Time.realtimeSinceStartup+seconds;while(!predicate()){if(Time.realtimeSinceStartup>end)throw new Exception("Timeout "+label);yield return null;}}
 void Update(){if(ended)return;if(wall!=null&&wall.rules.Active&&wall.rules.Points<2&&Time.unscaledTime>=diagnosticAt){diagnosticAt=Time.unscaledTime+.15f;Debug.Log("WB_DIAG phase="+wall.rules.Phase+" ball="+wall.ball.body.position+" v="+wall.ball.body.linearVelocity+" p0="+wall.trucks[0].body.position+" p1="+wall.trucks[1].body.position+" target1="+wall.agents[1].Target+" armed="+wall.Armed[1]);}try{while(stack.Count>0){var s=stack.Peek();if(!s.MoveNext()){stack.Pop();continue;}if(s.Current is IEnumerator child){stack.Push(child);continue;}return;}Finish(errors?2:0);}catch(Exception e){evidence.Add("FAIL "+e);Debug.LogError(e);Finish(2);}}
 void Finish(int code){ended=true;Time.timeScale=1;File.WriteAllLines(Path.Combine(folder,"existing-results.txt"),evidence);if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);InputSystem.settings=original;Destroy(probe);Application.Quit(code);}
 void Capture(string label){ScreenCapture.CaptureScreenshot(Path.Combine(folder,label+".png"));}
 IEnumerator Run(){yield return Delay(.5f);SportsNavigation.LoadSport(SportsNavigation.Hockey);yield return Delay(.5f);hockey=FindAnyObjectByType<HockeyMatch>();hockey.mode=HockeyMode.SharedKeyboard;hockey.Configure();hockey.durationMinutes=3;Check(hockey.StartMatch(),"hockey physical fixtures start six keyboard sources (no hardware input)");yield return Wait(()=>hockey.rules.Live,5,"hockey countdown");
  yield return Pair(false);yield return Pair(true);yield return StickCases();
  hockey.ChangeSetup();hockey.mode=HockeyMode.AIVsAI;hockey.Configure();hockey.durationMinutes=1;Check(hockey.StartMatch(),"six-AI match starts");Time.timeScale=3;yield return Wait(()=>hockey.rules.Phase==HockeyPhase.Finished,130,"complete six AI regulation/overtime");Note("Hockey full AI match goals="+hockey.rules.Goals+" strongHits="+hockey.impacts.StrongHits+" counters="+hockey.impacts.Counters+" neutralFaceoffs="+hockey.EmergencyFaceoffs);Time.timeScale=1;
  SportsNavigation.LoadSport(SportsNavigation.Wallball);yield return Delay(.5f);wall=FindAnyObjectByType<WallballMatch>();Check(wall.trucks.Length==8&&wall.menus.names.Length==8,"saved eight-truck Wallball scene");foreach(var sizes in new[]{new Vector2Int(1,1),new Vector2Int(2,2),new Vector2Int(4,4),new Vector2Int(1,4)}){wall.ChangeSetup();wall.blueSize=sizes.x;wall.orangeSize=sizes.y;wall.Configure(WallballMode.AIVsAI);wall.ChangeSetup();wall.Configure(WallballMode.AIVsAI);Check(wall.StartMatch(),"AI Wallball "+sizes.x+"v"+sizes.y+" starts");Time.timeScale=4;yield return Wait(()=>wall.rules.Phase==WallballPhase.Finished,240,"Wallball "+sizes.x+"v"+sizes.y+" match");Note("Wallball "+sizes.x+"v"+sizes.y+" score="+wall.rules.Score[0]+":"+wall.rules.Score[1]+" physicalReturns="+wall.PhysicalReturns+" legalReturns="+wall.LegalReturns+" hits="+wall.rules.Shots+" replays="+wall.Replays);Check(wall.PhysicalReturns>0&&wall.LegalReturns>0,"routine physical/legal returns "+sizes);Time.timeScale=1;}
  wall.ChangeSetup();wall.blueSize=wall.orangeSize=4;wall.Configure(WallballMode.AIVsAI);wall.StartMatch();yield return Delay(3);Screen.SetResolution(1280,720,false);yield return Delay(.5f);Capture("wallball-4v4-720");yield return Delay(.2f);Screen.SetResolution(1920,1080,false);yield return Delay(.5f);Capture("wallball-4v4-1080");yield return Delay(.2f);wall.Pause();Capture("wallball-pause");yield return Delay(.2f);
  SportsNavigation.LoadSport(SportsNavigation.Bowling);yield return Delay(.5f);bowling=FindAnyObjectByType<BowlingMatch>();bowling.setup.count=4;bowling.setup.mode=BowlingMode.Simultaneous;for(int i=0;i<4;i++)bowling.setup.players[i].source=BowlingSource.AI;Check(bowling.StartMatch(),"four independent AI bowling lanes start");Time.timeScale=4;bool lower=false,sweeping=false,returning=false,raising=false,setting=false;float until=Time.realtimeSinceStartup+400;while(!bowling.Finished){foreach(var lane in bowling.lanes){CheckLiveClear(lane);lower|=lane.Phase==BowlingPhase.Lowering;sweeping|=lane.Phase==BowlingPhase.Sweeping;returning|=lane.Phase==BowlingPhase.Returning;raising|=lane.Phase==BowlingPhase.Raising;setting|=lane.Phase==BowlingPhase.Setting;}if(Time.realtimeSinceStartup>until)throw new Exception("Bowling complete games timeout");yield return null;}Check(lower&&sweeping&&returning&&raising&&setting,"all overhead sweeper phases exercised in complete four-lane games");for(int i=0;i<4;i++)Note("Bowling lane="+i+" total="+bowling.setup.players[i].score.ResolvedTotal+" scoreLocks="+bowling.lanes[i].ScoreLocks+" sweeps="+bowling.lanes[i].Sweeps);Time.timeScale=1;SportsNavigation.FrontEnd();yield return Delay(.5f);Check(FindAnyObjectByType<SportsFrontEnd>()!=null,"returns to collection");
 }
 void CheckLiveClear(BowlingLane lane){if(lane.MotionLive&&(lane.sweep.position.y<2.8f||Mathf.Abs(lane.sweep.position.z-(lane.pinLine+lane.sweepFrontOffset))>.01f))throw new Exception("Live sweeper obstruction lane "+lane.index);}
 IEnumerator Pair(bool stopped){for(int i=0;i<6;i++)hockey.trucks[i].ResetBody(new Vector3(i<3?-12:12,.36f,(i%3-1)*5),Quaternion.identity);hockey.puck.position=new Vector3(0,.22f,7);hockey.puck.linearVelocity=Vector3.zero;var a=hockey.trucks[0];var b=hockey.trucks[3];a.ResetBody(new Vector3(-4,.36f,0),Quaternion.Euler(0,90,0));b.ResetBody(new Vector3(0,.36f,0),Quaternion.Euler(0,90,0));a.body.linearVelocity=Vector3.right*11;b.body.linearVelocity=Vector3.right*(stopped?0:2);Physics.SyncTransforms();int before=hockey.impacts.StrongHits;yield return Wait(()=>hockey.impacts.StrongHits>before,2,"physical pair "+stopped);var av=a.body.linearVelocity;var bv=b.body.linearVelocity;var bp=b.body.position;var ap=a.body.position;yield return Delay(.55f);Note("PHYSICAL "+(stopped?"stopped counter":"moving launch")+" postA="+av+" postB="+bv+" displacementA="+Vector3.Distance(a.body.position,ap)+" displacementB="+Vector3.Distance(b.body.position,bp));Check(stopped?av.x< -10&&bv.magnitude<1:bv.x>15,"actual solver-contact "+(stopped?"attacker rebounds, defender holds":"slower target launches"));Check(stopped?Vector3.Distance(b.body.position,bp)<.8f:Vector3.Distance(b.body.position,bp)>5,"physical displacement "+(stopped?"defender bounded":"several truck lengths"));}
 IEnumerator StickCases(){var t=hockey.trucks[0];t.ResetBody(new Vector3(0,.36f,0),Quaternion.identity);hockey.puck.position=new Vector3(10,.22f,0);yield return Delay(.7f);Check(t.stick.blade.enabled,"blade rearms on open ice with puck separated · "+t.stick.Diagnostic);InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W,Key.D));yield return Delay(.2f);Check(Quaternion.Angle(t.stick.bladeBody.rotation,t.body.rotation)>1,"stick visibly lags steering");InputSystem.QueueStateEvent(keyboard,new KeyboardState());t.ClearInput();t.ResetBody(new Vector3(0,.36f,hockey.halfWidth-.8f),Quaternion.Euler(0,90,0));yield return Delay(1.2f);Check(!t.stick.blade.enabled||t.stick.Side==1,"board-aware safe side or tuck");t.ResetBody(new Vector3(0,.36f,hockey.halfWidth-.8f),Quaternion.Euler(0,-90,0));yield return Delay(1.2f);Check(t.stick.Side==-1&&!t.stick.Tucked,"actual automatic side switch opens away from opposite board");int changes=t.stick.Switches;yield return Delay(1);Check(t.stick.Switches-changes<=1,"wall avoidance hysteresis prevents chatter");Capture("hockey-stick-wall");yield return Delay(.2f);}
 void OnDestroy(){Application.logMessageReceived-=Log;}
#endif
}
}
